    //
    // Twist
    //
    aIngress = 0xA814AC0C15E4397FULL;
    aCarry = 0xC7B8831116CB6DD4ULL;
    aWandererA = 0xCAB26D72DCD337B5ULL;
    aWandererB = 0xF712F7CAF799C8D8ULL;
    aWandererC = 0xA16B8EAB110549A6ULL;
    aWandererD = 0xD43EA2C2629124D4ULL;
