    aWandererF = 0xC6204677EC60D335ULL;
    aWandererG = 0x9DFEE4B4F9CE08CCULL;
    aWandererH = 0xB736F981107B4485ULL;
    aWandererI = 0x87832E1E6181E264ULL;
    aWandererJ = 0xC6372ECB340F43B3ULL;
    aWandererK = 0x9F93516735C4FFC1ULL;

    //
    TwistExpander_Antares_Arx::SEED_A(PARAMS_SEED);

    TwistExpander_Antares_Arx::SEED_B(PARAMS_SEED);

    TwistExpander_Antares_Arx::SEED_C(PARAMS_SEED);

    //
    std::uint64_t aDomainWordMatrixSelectA = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixSelectA;
    std::uint64_t aDomainWordMatrixSelectB = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixSelectB;
